#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i = 0; i < 10; i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);

    for(int i = 0; i < m; i++){
        int u, v; cin >> u >> v;
        adj[u].push_back(v);
        radj[v].push_back(u);
    }

    // Fast adjacency via sorted lists + binary search
    for(int i = 1; i <= n; i++){
        sort(adj[i].begin(), adj[i].end());
        sort(radj[i].begin(), radj[i].end());
    }

    auto has_edge = [&](int u, int v) -> bool {
        return binary_search(adj[u].begin(), adj[u].end(), v);
    };

    auto now = chrono::steady_clock::now;
    auto start_time = now();
    auto elapsed_ms = [&](){return chrono::duration_cast<chrono::milliseconds>(now()-start_time).count();};

    // Check DAG - topological sort for longest path
    {
        vector<int> indeg(n+1, 0);
        for(int u = 1; u <= n; u++) for(int v : adj[u]) indeg[v]++;
        queue<int> q;
        for(int u = 1; u <= n; u++) if(indeg[u] == 0) q.push(u);
        vector<int> topo;
        topo.reserve(n);
        while(!q.empty()){
            int u = q.front(); q.pop(); topo.push_back(u);
            for(int v : adj[u]) if(--indeg[v] == 0) q.push(v);
        }
        if((int)topo.size() == n){
            vector<int> dp(n+1, 1), nxt(n+1, -1);
            for(int i = n-1; i >= 0; i--){
                int u = topo[i]; dp[u] = 1; nxt[u] = -1;
                for(int v : adj[u]){
                    if(dp[v] + 1 > dp[u]){
                        dp[u] = dp[v] + 1;
                        nxt[u] = v;
                    }
                }
            }
            int bs = topo[0];
            for(int u : topo) if(dp[u] > dp[bs]) bs = u;
            vector<int> path;
            for(int u = bs; u != -1; u = nxt[u]) path.push_back(u);
            cout << path.size() << "\n";
            for(int i = 0; i < (int)path.size(); i++){
                if(i) cout << ' ';
                cout << path[i];
            }
            cout << "\n";
            return 0;
        }
    }

    mt19937 rng(42);
    vector<int> best_path;

    // For DFS on small graphs
    if(n <= 22 && elapsed_ms() < 3500){
        vector<bool> vis(n+1, false);
        vector<int> cur_path;
        bool found = false;
        function<void(int)> dfs = [&](int u){
            if(found || elapsed_ms() > 3700) return;
            cur_path.push_back(u); vis[u] = true;
            if((int)cur_path.size() > (int)best_path.size()) best_path = cur_path;
            if((int)cur_path.size() == n){ found = true; vis[u] = false; cur_path.pop_back(); return; }
            vector<pair<int,int>> nb;
            for(int v : adj[u]) if(!vis[v]){
                int c = 0; for(int w : adj[v]) if(!vis[w]) c++;
                nb.push_back({c, v});
            }
            sort(nb.begin(), nb.end());
            for(auto&[c,v] : nb){
                if(found || elapsed_ms() > 3700) break;
                dfs(v);
            }
            vis[u] = false; cur_path.pop_back();
        };
        vector<int> order(n);
        iota(order.begin(), order.end(), 1);
        // Sort by out-degree ascending for starting
        sort(order.begin(), order.end(), [&](int a, int b){ return adj[a].size() < adj[b].size(); });
        for(int s : order){
            if(found || elapsed_ms() > 3500) break;
            dfs(s);
        }
        if(found){
            cout << best_path.size() << "\n";
            for(int i = 0; i < (int)best_path.size(); i++){
                if(i) cout << ' ';
                cout << best_path[i];
            }
            cout << "\n";
            return 0;
        }
    }

    // Main heuristic: multi-restart greedy + directed rerouting + vertex insertion
    vector<int> pos(n+1, -1);

    auto do_run = [&](int sv) -> vector<int> {
        // Reset pos
        vector<int> path;
        path.reserve(n);
        path.push_back(sv);
        // Use a visited array
        vector<bool> used(n+1, false);
        used[sv] = true;

        // Warnsdorff extend back
        auto extend_back = [&]() -> bool {
            int c = path.back();
            int best = -1, best_score = INT_MAX;
            for(int v : adj[c]){
                if(used[v]) continue;
                int s = 0;
                for(int w : adj[v]) if(!used[w]) s++;
                if(s < best_score || (s == best_score && (rng()&1))){
                    best_score = s; best = v;
                }
            }
            if(best == -1) return false;
            used[best] = true;
            path.push_back(best);
            return true;
        };

        // Warnsdorff extend front
        auto extend_front = [&]() -> bool {
            int c = path.front();
            int best = -1, best_score = INT_MAX;
            for(int v : radj[c]){
                if(used[v]) continue;
                int s = 0;
                for(int w : radj[v]) if(!used[w]) s++;
                if(s < best_score || (s == best_score && (rng()&1))){
                    best_score = s; best = v;
                }
            }
            if(best == -1) return false;
            used[best] = true;
            path.insert(path.begin(), best);
            return true;
        };

        // Use deque internally then convert
        deque<int> dq;
        dq.push_back(sv);
        // Redo with deque
        path.clear();
        used.assign(n+1, false);
        used[sv] = true;

        auto dq_extend_back = [&]() -> bool {
            int c = dq.back();
            int best = -1, best_score = INT_MAX;
            for(int v : adj[c]){
                if(used[v]) continue;
                int s = 0;
                for(int w : adj[v]) if(!used[w]) s++;
                if(s < best_score || (s == best_score && (rng()&1))){
                    best_score = s; best = v;
                }
            }
            if(best == -1) return false;
            used[best] = true;
            dq.push_back(best);
            return true;
        };

        auto dq_extend_front = [&]() -> bool {
            int c = dq.front();
            int best = -1, best_score = INT_MAX;
            for(int v : radj[c]){
                if(used[v]) continue;
                int s = 0;
                for(int w : radj[v]) if(!used[w]) s++;
                if(s < best_score || (s == best_score && (rng()&1))){
                    best_score = s; best = v;
                }
            }
            if(best == -1) return false;
            used[best] = true;
            dq.push_front(best);
            return true;
        };

        for(int round = 0; round < 3; round++){
            while(dq_extend_back());
            while(dq_extend_front());
        }

        path.assign(dq.begin(), dq.end());

        // Directed rerouting iterations
        // When stuck at tail: find tail->path[j], truncate to path[0..j], free path[j+1..end-1], re-extend
        // When stuck at head: find path[j]->head (i.e., radj[head] contains path[j]), truncate to path[j..end], free path[0..j-1], re-extend

        auto rebuild_pos = [&](){
            // not needed if we use 'used' array
        };

        int best_len = (int)path.size();

        for(int iter = 0; iter < 500 && elapsed_ms() < 3750; iter++){
            if((int)path.size() >= n) break;

            bool improved = false;

            // Try tail rerouting
            {
                int tail = path.back();
                vector<int> candidates;
                for(int v : adj[tail]){
                    // find position of v in path
                    // We need pos array
                    // Let's maintain it
                }
                // Rebuild pos
                for(int i = 0; i < (int)path.size(); i++) pos[path[i]] = i;

                for(int v : adj[tail]){
                    if(pos[v] >= 0 && pos[v] < (int)path.size()-1){
                        candidates.push_back(pos[v]);
                    }
                }

                if(!candidates.empty()){
                    // Pick randomly
                    int j = candidates[rng() % candidates.size()];
                    // Check: does path[j+1] have any unvisited out-neighbor?
                    int pj1 = path[j+1];
                    bool has_unvis = false;
                    for(int w : adj[pj1]) if(!used[w]){ has_unvis = true; break; }

                    if(has_unvis || (rng()%3 == 0)){
                        // Reroute: new path = path[0..j] + tail
                        // Free vertices path[j+1..end-2] (tail stays as path[j+1] in new path? No.)
                        // Actually: path is path[0],...,path[j], path[j+1],...,path[end-1=tail]
                        // We have edge tail->path[j]. But we want tail AFTER path[j], which means
                        // path[j]->tail must exist. We have tail->path[j], not path[j]->tail.

                        // So we can't just append tail after path[j].
                        // What we CAN do: reverse the segment path[j+1..end] if all reverse edges exist.
                        // That's unlikely in directed graphs.

                        // Alternative strategy: just truncate at j+1, freeing path[j+2..end-1]
                        // (keep path[0..j+1]), then re-extend from path[j+1]

                        // Better: truncate everything after some random point and re-extend
                        int cut = j + 1; // keep path[0..cut]
                        int old_size = (int)path.size();
                        for(int i = cut+1; i < old_size; i++){
                            used[path[i]] = false;
                            pos[path[i]] = -1;
                        }
                        path.resize(cut+1);

                        // Re-extend back
                        while(true){
                            int c = path.back();
                            int bv = -1, bs = INT_MAX;
                            for(int w : adj[c]){
                                if(used[w]) continue;
                                int sc = 0;
                                for(int x : adj[w]) if(!used[x]) sc++;
                                if(sc < bs || (sc == bs && (rng()&1))){
                                    bs = sc; bv = w;
                                }
                            }
                            if(bv == -1) break;
                            used[bv] = true;
                            pos[bv] = (int)path.size();
                            path.push_back(bv);
                        }

                        if((int)path.size() > best_len){
                            best_len = (int)path.size();
                            improved = true;
                        }
                    }
                }
            }

            // Try head rerouting
            {
                int head = path[0];
                for(int i = 0; i < (int)path.size(); i++) pos[path[i]] = i;

                vector<int> candidates;
                for(int v : radj[head]){
                    if(pos[v] >= 0 && pos[v] > 0){
                        candidates.push_back(pos[v]);
                    }
                }

                if(!candidates.empty()){
                    int j = candidates[rng() % candidates.size()];
                    int pjm1 = path[j-1];
                    bool has_unvis = false;
                    for(int w : radj[pjm1]) if(!used[w]){ has_unvis = true; break; }

                    if(has_unvis || (rng()%3 == 0)){
                        int cut = j; // keep path[cut..end]
                        for(int i = 0; i < cut; i++){
                            used[path[i]] = false;
                            pos[path[i]] = -1;
                        }
                        path.erase(path.begin(), path.begin()+cut);

                        // Re-extend front using deque trick: reverse, extend back, reverse
                        // Or just do it directly
                        // Extend front
                        deque<int> dq2(path.begin(), path.end());
                        while(true){
                            int c = dq2.front();
                            int bv = -1, bs = INT_MAX;
                            for(int w : radj[c]){
                                if(used[w]) continue;
                                int sc = 0;
                                for(int x : radj[w]) if(!used[x]) sc++;
                                if(sc < bs || (sc == bs && (rng()&1))){
                                    bs = sc; bv = w;
                                }
                            }
                            if(bv == -1) break;
                            used[bv] = true;
                            dq2.push_front(bv);
                        }
                        path.assign(dq2.begin(), dq2.end());
                        for(int i = 0; i < (int)path.size(); i++) pos[path[i]] = i;

                        if((int)path.size() > best_len){
                            best_len = (int)path.size();
                            improved = true;
                        }
                    }
                }
            }

            // Vertex insertion
            if(iter % 10 == 0){
                for(int i = 0; i < (int)path.size(); i++) pos[path[i]] = i;
                for(int v = 1; v <= n; v++){
                    if(used[v]) continue;
                    // Try insert between path[i] and path[i+1]
                    for(int i = 0; i+1 < (int)path.size(); i++){
                        if(has_edge(path[i], v) && has_edge(v, path[i+1])){
                            path.insert(path.begin()+i+1, v);
                            used[v] = true;
                            for(int j = i+1; j < (int)path.size(); j++) pos[path[j]] = j;
                            improved = true;
                            break;
                        }
                    }
                    if(used[v]) continue;
                    // Prepend
                    if(has_edge(v, path[0])){
                        path.insert(path.begin(), v);
                        used[v] = true;
                        for(int j = 0; j < (int)path.size(); j++) pos[path[j]] = j;
                        improved = true;
                        continue;
                    }
                    // Append
                    if(has_edge(path.back(), v)){
                        pos[v] = (int)path.size();
                        path.push_back(v);
                        used[v] = true;
                        improved = true;
                        continue;
                    }
                }
                best_len = max(best_len, (int)path.size());
            }
        }

        return path;
    };

    // Multi-restart
    vector<int> starts(n);
    iota(starts.begin(), starts.end(), 1);
    shuffle(starts.begin(), starts.end(), rng);

    for(int si = 0; si < n && elapsed_ms() < 3750; si++){
        auto p = do_run(starts[si]);
        if((int)p.size() > (int)best_path.size()){
            best_path = p;
            if((int)best_path.size() >= n) break;
        }
    }

    // Final vertex insertion pass on best_path
    if((int)best_path.size() < n){
        vector<bool> used(n+1, false);
        for(int v : best_path) used[v] = true;

        for(int v = 1; v <= n; v++){
            if(used[v]) continue;
            // Insert
            bool inserted = false;
            for(int i = 0; i+1 < (int)best_path.size(); i++){
                if(has_edge(best_path[i], v) && has_edge(v, best_path[i+1])){
                    best_path.insert(best_path.begin()+i+1, v);
                    used[v] = true;
                    inserted = true;
                    break;
                }
            }
            if(inserted) continue;
            if(has_edge(v, best_path[0])){
                best_path.insert(best_path.begin(), v);
                used[v] = true;
                continue;
            }
            if(has_edge(best_path.back(), v)){
                best_path.push_back(v);
                used[v] = true;
                continue;
            }
        }
    }

    cout << best_path.size() << "\n";
    for(int i = 0; i < (int)best_path.size(); i++){
        if(i) cout << ' ';
        cout << best_path[i];
    }
    cout << "\n";
    return 0;
}
